import { useSearchParams } from "react-router-dom";
import { useParcels } from "./useParcels";
import { useAddParcel } from "./useAddParcel";
import { useAddParcelForm } from "./useAddParcelForm";
import { useAddParcelErrorBanner } from "./useAddParcelErrorBanner";

export const ParcelPickupPointDesk = () => {
  const [searchParams] = useSearchParams();
  const [recipientName, setRecipientName] = useState("");
  const [status, setStatus] = useState("waiting");
  const [searchResults, setSearchResults] = useState<Parcel[]>([]);
  const [addParcelForm, addParcelFormErrorBanner] = useAddParcelForm();
  const [addParcelErrorBanner, addParcelErrorBannerErrorBanner] =
    useAddParcelErrorBanner();
  const [addParcelErrorBannerErrorBannerErrorBanner] =
    useAddParcelErrorBannerErrorBanner();

  useEffect(() => {
    const fetchParcels = async () => {
      const parcels = await useParcels();
      setSearchResults(parcels);
    };

    fetchParcels();
  }, []);

  const handleSearch = (e: React.ChangeEvent<HTMLInputElement>) => {
    setRecipientName(e.target.value);
  };

  const handleStatusChange = (e: React.ChangeEvent<HTMLSelectElement>) => {
    setStatus(e.target.value);
  };

  const handleAddParcel = async (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();

    const addParcelResult = await useAddParcel({
      recipientName,
      status,
      searchResults,
    });

    if (addParcelResult.error) {
      addParcelErrorBannerErrorBannerErrorBanner(addParcelResult.error);
      return;
    }

    addParcelFormErrorBanner(addParcelResult.error);
    setSearchResults([]);
  };

  const handleAddParcelForm = (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();

    const addParcelFormResult = await useAddParcelForm({
      recipientName,
      status,
      searchResults,
    });

    if (addParcelFormResult.error) {
      addParcelFormErrorBannerErrorBanner(addParcelFormResult.error);
      return;
    }

    addParcelFormErrorBanner(addParcelFormResult.error);
    setSearchResults([]);
  };

  const handleAddParcelErrorBanner = (error: string) => {
    addParcelErrorBannerErrorBanner(error);
  };

  const handleAddParcelErrorBannerErrorBanner = (error: string) => {
    addParcelErrorBannerErrorBannerErrorBanner(error);
  };

  return (
    <div>
      <h1>Parcel Pickup Point Desk</h1>
      <input
        type="text"
        placeholder="Recipient Name"
        value={recipientName}
        onChange={handleSearch}
      />
      <select value={status} onChange={handleStatusChange}>
        <option value="waiting">Waiting</option>
        <option value="picked-up">Picked Up</option>
        <option value="returned">Returned</option>
      </select>
      <button onClick={handleAddParcel}>Add Parcel</button>
      <form onSubmit={handleAddParcelForm}>
        <input type="text" placeholder="Recipient Name" value={recipientName} onChange={handleSearch} />
        <select value={status} onChange={handleStatusChange}>
          <option value="waiting">Waiting</option>
          <option value="picked-up">Picked Up</option>
          <option value="returned">Returned</option>
        </select>
        <button type="submit">Add Parcel</button>
      </form>
      {addParcelFormErrorBanner && (
        <div className="add-parcel-form-error-banner">
          {addParcelFormErrorBannerErrorBanner}
        </div>
      )}
      {addParcelErrorBanner && (
        <div className="add-parcel-error-banner">
          {addParcelErrorBannerErrorBanner}
        </div>
      )}
    </div>
  );
};
